import mongomock

def class_summary(collection, minimum):
    pipeline = [
        {'$match': {'scores.Computing': {'$gte': minimum}}},
        {'$group': {'_id': '$class', 'average': {'$avg': '$scores.Computing'}, 'count': {'$sum': 1}}},
        {'$sort': {'average': -1, '_id': 1}}
    ]
    return list(collection.aggregate(pipeline))
